$ErrorActionPreference='Stop'
Write-Host 'STORM: DRAGONIUM OUTRAGEOUS +20 2S; 2 ORBS; 3 ARCANA+20; SAGE BELT+20; CARNELIAN+20; MILEAGE+10000'
Write-Host 'AIZVER SPELI; TIKAI TESTA VM 192.168.56.101; ITEMI BUS PASTA'
$code=[Text.Encoding]::ASCII.GetString([Convert]::FromBase64String(''))
$rows=@($code | ssh root@192.168.56.101 python3 - --apply)
$result=$LASTEXITCODE
$rows | ForEach-Object { Write-Host $_ }
$report=Join-Path $env:USERPROFILE ('Downloads\Storm-Outrageous-Receipt-'+(Get-Date -Format 'yyyyMMdd-HHmmss')+'.txt')
$rows | Set-Content -LiteralPath $report -Encoding UTF8
Write-Host ('REPORT='+$report)
if($result -ne 0 -or !($rows | Select-String -SimpleMatch 'STORM_EPIC_REPAIR_CONFIRMED;','STORM_EPIC_REPAIR_ALREADY_GRANTED;')){throw 'STORM_EPIC_REPAIR_NOT_CONFIRMED; ATSUTI_IZVADI'}
